WHERE NOT EXISTS (SELECT 1 FROM asset x WHERE x.asset_code = v.code);

-- Sanity check: should return 5184 / 5184 / 0 after a first successful run.
SELECT
    (SELECT count(*) FROM asset_code) AS asset_codes_total,
    (SELECT count(*) FROM asset)      AS assets_total,
    (SELECT count(*) FROM asset a LEFT JOIN asset_code c ON c.asset_code_id = a.asset_code_id WHERE c.asset_code_id IS NULL) AS orphan_assets;

COMMIT;
